/// <summary>
/// This is a service class
/// CB387_DallasPickListRegistration
/// </summary>
final class METDallasPicklistRegService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// This method split out the bundles
    /// </summary>
    /// <param name = "_dataContract">Contract</param>
    public void processOperation(METDallasPicklistRegContract _dataContract)
    {   
        #OCCRetryCount

        WMSOrderTrans                   wmsOrderTrans;
        METDallasPicklistRegContract    metDataContract;
        SysOperationServiceController   controller;
        Int                             bundlesize; 
        container                       conOrdTrans, conOrdTransRoute;
        BatchHeader                     batchHeader;
        int                             counter     = 0;
        int                             totalTasks  = _dataContract.parmParallelTasksNumber() ;
        Int                             numOfOrders;
        boolean                         processExtInvSO = _dataContract.parmProcessExtInvSo();
        Query                           query = _dataContract.getQuery();
        Set                             taskSet = new Set(Types::Class);
        Set                             routeIdSet = new Set(Types::String);             

        // --- Apply filter based on ExternalInvoiceOrder flag -- -
        if (!processExtInvSO)
        {
            QueryBuildDataSource qbdsWmsOrderTrans, qbdsWmsPickingRoute;
            qbdsWmsOrderTrans = query.dataSourceTable(tableNum(WmsOrderTrans));

            qbdsWmsPickingRoute = qbdsWmsOrderTrans.addDataSource(tableNum(WMSPickingRoute));
            qbdsWmsPickingRoute.relations(false);
            qbdsWmsPickingRoute.joinMode(JoinMode::ExistsJoin);
            qbdsWmsPickingRoute.addLink(fieldNum(WmsOrderTrans, routeId), fieldNum(WMSPickingRoute, pickingRouteID));
       
            qbdsWmsPickingRoute.addRange(fieldNum(WMSPickingRoute, METExternalInvoicedSO))
                                  .value(SysQuery::value(NoYes::No));
        }

        METProcMetrics procMetrics   = METProcMetrics::construct(METBatchLogOperation::DallasPicklistRegistration);

        if (totalTasks  <= 0)
        {
            totalTasks  = 1;
        }

        batchHeader     = this.getCurrentBatchHeader();

        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }
        
        try
        {
            // Populate the map to group WMSOrderTrans by routeId
            QueryRun queryRun = new QueryRun(query);

            numOfOrders = QueryRun::getQueryRowCount(query, intMax());
            bundleSize = real2int(roundUp((numOfOrders / totalTasks), 1.0));
            
            procMetrics.setTotalCountFromQuery(queryRun);
            procMetrics.beginTrace('Process started');
            
            using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
            {
                while (queryRun.next())
                {
                    wmsOrderTrans = queryRun.get(tableNum(WMSOrderTrans));

                    routeIdSet.add(wmsOrderTrans.routeId);

                    counter += 1;

                    if (counter == 1)
                    {
                        conOrdTrans = conNull();
                    }

                    conOrdTrans += wmsOrderTrans.RecId;

                    if (counter == bundlesize)
                    {
                        controller      = new SysOperationServiceController(
                                                classStr(METPickingListRegistrationPostingJob),
                                                methodStr(METPickingListRegistrationPostingJob, postPickListRegistration));

                        controller.parmDialogCaption(strFmt("@MET:PostPackingSlipSubTask", counter));

                        metDataContract = controller.getDataContractObject() as METDallasPicklistRegContract;
                        metDataContract.parmConOrderTrans(conOrdTrans);

                        batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
                    
                        counter = 0;

                        taskSet.add(controller);
                    }
                }
  
                if (counter > 0)
                {
                    controller      = new SysOperationServiceController(
                                                classStr(METPickingListRegistrationPostingJob),
                                                methodStr(METPickingListRegistrationPostingJob, postPickListRegistration));

                    controller.parmDialogCaption(strFmt("@MET:PostPackingSlipSubTask", counter));

                    metDataContract = controller.getDataContractObject() as METDallasPicklistRegContract ;
                    metDataContract.parmConOrderTrans(conOrdTrans);

                    batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

                    taskSet.add(controller);
                }

                this.addDallasPicklistRegCompleteTask(routeIdSet, taskSet, totalTasks, batchHeader);

                batchHeader.save();

                procMetrics.endTrace() ;
            }
        }
        catch(Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:UnHandledDallasError",
                 Global::exceptionTextFallThrough()));
            error(strFmt("@MET:CallStackErr", xSession::xppCallStack()));
        }
    }

    /// <summary>
    /// Get the count of order trans
    /// </summary>
    /// <returns>Count</returns>
    private int countOrderTrans()
    {
        WMSOrderTrans   wmsOrderTransLoc;
        int             numberOfOpenRecord;

        select count(RecId) from wmsOrderTransLoc 
            where   wmsOrderTransLoc.METPickedQtyUpdated == NoYes::Yes
            &&      wmsOrderTransLoc.METPickedQtyProcessed == NoYes::No;

        numberOfOpenRecord = int642int(wmsOrderTransLoc.RecId);

        return numberOfOpenRecord;
    }

    /// <summary>
    /// Adds a picklist registation complete task to the batch header and establishes dependencies with other tasks.
    /// </summary>
    /// <param name = "_routeIdSet">Route Id set.</param>
    /// <param name = "_taskSet">Task Id set.</param>
    /// <param name = "_tasksNumber">Task number.</param>
    /// <param name = "_batchHeader">Batch header.</param>
    private void addDallasPicklistRegCompleteTask(Set _routeIdSet, Set _taskSet, int _tasksNumber, BatchHeader _batchHeader)
    {
        SysOperationServiceController controller =  METDallasPicklistRegCompleteController::construct(_routeIdSet.pack(), _tasksNumber);
        
        SetEnumerator taskEnum = _taskSet.getEnumerator() as SetEnumerator;

        _batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

        while (taskEnum && taskEnum.moveNext())
        {
            SysOperationServiceController transactionTaskController = taskEnum.current();
            _batchHeader.addDependency(controller, transactionTaskController, BatchDependencyStatus::FinishedOrError);
        }
    }
